/* Affiliate calls to action are entirely absent while the programme is inactive. */
.aff-card .am-affiliate-cta{display:inline-flex;justify-content:center;align-items:center;min-height:44px;padding:10px 13px;margin-top:8px;width:100%;background:#173d2b;color:#fff;border:1px solid #173d2b;font-size:12px;font-weight:700;letter-spacing:.02em;text-decoration:none;text-align:center;line-height:1.45}
.aff-card .am-affiliate-cta:hover{background:#305943}
.aff-card .am-affiliate-note{display:block;margin:5px 0 8px;color:#536b5b;font-size:11px;line-height:1.55}
.detail-cta.am-affiliate-detail{display:inline-flex;background:#193d29;color:#fff;border-color:#193d29;margin:8px 8px 16px 0}
.detail-cta.am-affiliate-detail:hover{background:#345b43}
.am-affiliate-cta:focus-visible,.am-affiliate-detail:focus-visible{outline:3px solid #b99760;outline-offset:3px}
@media(max-width:620px){.aff-card .am-affiliate-cta{min-height:48px}.detail-cta.am-affiliate-detail{width:100%}}

'use strict';
/* Verified Amazon.fr product matches first; compensated links only when authorised. */
(() => {
  const statement='En tant que Partenaire Amazon, je réalise un bénéfice sur les achats remplissant les conditions requises';
  const code=/^[A-Z0-9]{10}$/;
  const watchId=/^[a-z0-9-]{4,64}$/;
  const isAmazon=(url,asin,tag)=>{
    try {
      const u=new URL(url);
      if(u.protocol!=='https:'||u.hostname!=='www.amazon.fr'||u.username||u.password||u.port||u.hash||
         u.pathname!=='/dp/'+asin)return false;
      if(tag===null)return u.search==='';
      return u.searchParams.getAll('tag').length===1 &&
        u.searchParams.get('tag')===tag &&
        [...u.searchParams.keys()].every(k=>k==='tag'||k==='th'||k==='psc');
    } catch {return false}
  };
  const get=async(path)=>{
    try {const r=await fetch(path,{cache:'no-store'});return r.ok?await r.json():null}
    catch {return null}
  };
  async function init() {
    const home=document.getElementById('affGrid'),detail=document.getElementById('detailShell');
    if(!home&&!detail)return;
    const [catalog,config,feed]=await Promise.all([
      get('./amazon-product-links.json'),get('./affiliate-links.json'),get('./selection-affiliation.json')
    ]);
    if(!Array.isArray(feed?.products)||feed.products.length!==15)return;
    const models=new Map(feed.products.filter(p=>watchId.test(p?.id||'')).map(p=>[p.id,p]));
    const plain=new Map();
    if(catalog?.version===1&&catalog.links&&!Array.isArray(catalog.links)) {
      for(const [id,entry] of Object.entries(catalog.links)) {
        if(!models.has(id)||!code.test(entry?.asin||'')||!isAmazon(entry.url,entry.asin,null))continue;
        plain.set(id,entry.url);
      }
    }
    const paid=new Map();
    if(config?.version===1&&config.enabled===true&&
       (config.approved===true&&(!config.enrollmentStatus||config.enrollmentStatus==='approved')||
        config.approved===false&&config.enrollmentStatus==='registered_pending_review'&&
        config.ownerConfirmedEnrollment===true&&config.specialLinksCreatedInAccount===true||
        config.approved===false&&config.enrollmentStatus==='enrolled_approval_unverified'&&
        config.ownerConfirmedEnrollment===true&&config.ownerConfirmedTrackingId===true&&
        config.ownerConfirmedSiteListed===true&&config.specialLinksCreatedOnSite===true&&
        config.specialLinksCreatedInAccount!==true)&&
       typeof config.amazonPartnerTag==='string'&&/^[a-z0-9][a-z0-9-]{1,48}-21$/i.test(config.amazonPartnerTag)&&
       config.links&&!Array.isArray(config.links)) {
      const entries=Object.entries(config.links);
      if(entries.length&&entries.every(([id,item])=>
          models.get(id)?.photoReview?.publicUsageApproved===true &&
          item?.provider==='amazon.fr'&&item.productMatchConfirmed===true&&item.linkApproved===true &&
          code.test(item.asin||'')&&isAmazon(item.url,item.asin,config.amazonPartnerTag)&&
          plain.get(id)==='https://www.amazon.fr/dp/'+item.asin)) {
        for(const [id,item] of entries)paid.set(id,item.url);
      }
    }
    const makeLink=(url,compensated,cls,id,placement)=>{
      const a=document.createElement('a');
      a.className=cls;a.href=url;a.target='_blank';
      a.dataset.amazonProduct=id;
      a.dataset.amazonPlacement=placement;
      a.rel=compensated?'noopener noreferrer nofollow sponsored':'noopener noreferrer nofollow';
      a.textContent=compensated?'Voir sur Amazon.fr · lien rémunéré ↗':'Voir sur Amazon.fr · lien non rémunéré ↗';
      return a;
    };
    function hydrateGrid() {
      for(const card of home?.querySelectorAll('.aff-card[data-watch-id]:not([data-affiliate-hydrated])')||[]) {
        card.dataset.affiliateHydrated='true';
        const id=card.dataset.watchId;
        const url=paid.get(id)||plain.get(id);
        if(!url)continue;
        const compensated=paid.has(id);
        const actions=card.querySelector('.aff-card-actions');
        if(!actions)continue;
        actions.append(makeLink(url,compensated,'am-affiliate-cta',id,'catalogue'));
        const foot=card.querySelector('.aff-card-foot');
        if(foot)foot.textContent=compensated?
          'Fiche Amazon vérifiée · lien rémunéré':
          'Fiche Amazon vérifiée · lien non rémunéré';
        const note=document.createElement('small');note.className='am-affiliate-note';
        note.textContent=compensated?
          'Lien rémunéré · Une commission peut nous être versée. Achat et retours chez le marchand indiqué.':
          'Prix et disponibilité à vérifier sur Amazon.fr. Aucun paiement n’est encaissé ici.';
        actions.after(note);
      }
    }
    if(home) {
      // The Amazon Associates statement belongs once in the prominent
      // catalogue transparency section. A per-card disclosure still labels
      // every commissionable link clearly without duplicating a paragraph.
      if(paid.size){
        const disclosure=document.querySelector('.aff-disclosure');
        if(disclosure&&!disclosure.textContent.includes(statement)){
          const line=document.createElement('p');
          line.className='am-affiliate-global-disclosure';
          line.textContent=statement+'. Les achats et retours s’effectuent chez Amazon ou le marchand indiqué.';
          disclosure.append(line);
        }
      }
      hydrateGrid();
      new MutationObserver(hydrateGrid).observe(home,{childList:true});
    }
    function hydrateDetail() {
      if(!detail||detail.hidden||detail.dataset.affiliateHydrated==='true')return;
      const id=new URLSearchParams(location.search).get('id');
      const url=paid.get(id)||plain.get(id);
      if(!url)return;
      const compensated=paid.has(id);
      detail.dataset.affiliateHydrated='true';
      const amazon=document.getElementById('detailAmazon');
      if(amazon) {
        amazon.href=url;
        amazon.dataset.amazonProduct=id;
        amazon.dataset.amazonPlacement='fiche';
        amazon.rel=compensated?'noopener noreferrer nofollow sponsored':'noopener noreferrer nofollow';
        amazon.textContent=compensated?'Voir sur Amazon.fr · lien rémunéré ↗':'Voir ce modèle sur Amazon.fr ↗';
      }
      const sub=detail.querySelector('.detail-sub');
      if(sub)sub.textContent=compensated?
        'Lien Amazon rémunéré. Consultez prix, disponibilité et vendeur chez Amazon.':
        'Fiche Amazon vérifiée, lien non rémunéré. Vérifiez le prix, la disponibilité et le vendeur.';
      if(compensated) {
        const official=document.getElementById('detailOfficial');
        if(official)official.before(makeLink(url,true,'button detail-cta am-affiliate-detail',id,'fiche'));
        if(amazon)amazon.hidden=true; // One clear paid call-to-action, not duplicate exits.
        const msg=detail.querySelector('.detail-disclosure');
        if(msg)msg.textContent='Lien rémunéré : '+statement+'. Aucun paiement n’est encaissé par Atelier Montres.';
        const footer=document.querySelector('.footer-inner>div>p');
        if(footer)footer.textContent='Sélection multimarque · certains liens Amazon rémunérés clairement signalés.';
      }
    }
    if(detail) {
      hydrateDetail();
      new MutationObserver(hydrateDetail).observe(detail,{attributes:true,attributeFilter:['hidden']});
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();

.aff-hero{background:#182820;color:#fff;overflow:hidden}.aff-hero-inner{min-height:650px;display:grid;grid-template-columns:1.1fr .9fr;gap:34px;align-items:center}.aff-copy{position:relative;z-index:2;padding:80px 0}.aff-copy h1{font:400 clamp(52px,6.9vw,104px)/1.03 Georgia,serif;letter-spacing:-.05em;max-width:800px;margin:0 0 24px}.aff-copy h1 em{color:#e0c79a}.aff-copy>p:not(.overline):not(.aff-note){color:#d6e1d8;max-width:520px;font-size:17px;line-height:1.82;margin:0 0 32px}.aff-note{font-size:12px;color:#aebcaf;margin-top:26px;max-width:480px}.aff-hero-scene{position:relative;height:570px;display:grid;place-items:center;isolation:isolate}.aff-orbit{width:460px;height:460px;border:1px solid #e0c99b44;border-radius:50%;position:absolute;box-shadow:0 0 0 55px #dabd9010}.aff-stage-strap{position:absolute;height:390px;width:135px;background:linear-gradient(90deg,#354238,#b0b6a5 25%,#4a5f52 52%,#d7d9c3 76%,#324a39);transform:rotate(-18deg);border-radius:19px;box-shadow:18px 26px 25px #07110a77}.aff-stage-dial{position:relative;width:238px;height:238px;border:13px solid #d5bd8b;border-radius:50%;background:radial-gradient(circle at 32% 29%,#497f6a,#0d271a 72%);transform:rotate(-18deg);box-shadow:0 0 0 4px #8e7551,20px 29px 28px #0008}.aff-stage-dial:before,.aff-stage-dial:after{content:"";position:absolute;bottom:50%;left:50%;width:5px;background:#e9d0a5;transform-origin:bottom center;border-radius:4px}.aff-stage-dial:before{height:66px;transform:rotate(35deg)}.aff-stage-dial:after{height:87px;transform:rotate(-105deg)}.aff-stage-dial span{position:absolute;top:calc(50% - 6px);left:calc(50% - 6px);width:12px;height:12px;border-radius:50%;background:#f0d69f;z-index:1}.aff-hero-legend{position:absolute;bottom:35px;right:0;color:#c5b998;letter-spacing:.21em;font-size:10px}.aff-tiers{background:#ede9e0}.aff-tier-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#d9d2c4}.aff-tier-grid>a{background:#f6f2ea;min-height:185px;padding:37px 29px;text-decoration:none;display:flex;flex-direction:column}.aff-tier-grid>a:hover{background:#eae2d1}.aff-tier-grid span{font-size:10px;letter-spacing:.18em;color:#97774a;text-transform:uppercase}.aff-tier-grid strong{font:400 37px Georgia,serif;margin-top:12px}.aff-tier-grid small{font-size:12px;color:#68756a;margin-top:7px}.aff-selection{padding:94px 0 112px;background:#fcfaf6}.aff-heading{display:grid;grid-template-columns:1.3fr .7fr;align-items:end;gap:55px;margin-bottom:28px}.aff-heading>p{max-width:470px;color:#5e6a61;line-height:1.77}.aff-disclosure{border-left:4px solid #b39a71;background:#f3eee5;padding:16px 21px;margin-bottom:31px;color:#405447}.aff-disclosure strong{font-size:13px}.aff-disclosure p{font-size:12px;line-height:1.75;margin:6px 0 0}.aff-tools{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:28px}.aff-tabs{display:flex;flex-wrap:wrap;gap:8px}.aff-tabs button{background:#fff;border:1px solid #cfc5b4;color:#273d2f;font:650 12px system-ui;padding:12px 14px;cursor:pointer}.aff-tabs button[aria-pressed=true]{background:#1c3727;color:#fff;border-color:#1c3727}.aff-query input{padding:12px 14px;border:1px solid #d0c7b8;background:white;min-width:min(300px,85vw);font-size:13px}.aff-result{color:#718075;font-size:13px;margin:20px 0}.aff-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.aff-card{min-width:0;background:#fff;border:1px solid #e4ded3;overflow:hidden;display:flex;flex-direction:column}.aff-illustration{height:235px;display:grid;place-items:center;background:linear-gradient(135deg,#eae7df,#d5dbd1);position:relative;isolation:isolate}.aff-illustration[data-tone=black]{background:linear-gradient(140deg,#506155,#202d2b)}.aff-illustration[data-tone=blue]{background:linear-gradient(140deg,#7c9dab,#21374b)}.aff-illustration[data-tone=green]{background:linear-gradient(140deg,#4d806e,#1a372a)}.aff-illustration[data-tone=turquoise]{background:linear-gradient(140deg,#a0ccc1,#446c73)}.aff-illustration[data-tone=ivory]{background:linear-gradient(140deg,#edddba,#adb19d)}.aff-illustration[data-tone=transparent]{background:linear-gradient(135deg,#d3e8e0,#819baa)}.aff-illustration[data-tone=silver]{background:linear-gradient(135deg,#d9d9d3,#9caba6)}.aff-illustration:before{content:'';position:absolute;width:184px;height:184px;border:1px solid #ffffff55;border-radius:50%}.aff-band{position:absolute;height:204px;width:65px;background:linear-gradient(90deg,#65736b,#cbd3cd 23%,#5c7064 51%,#d8ded0 75%,#51685a);transform:rotate(-17deg);border-radius:14px;filter:drop-shadow(8px 11px 8px #0004)}.aff-case{height:128px;width:128px;border:8px solid #dbccaa;border-radius:50%;background:radial-gradient(circle at 30% 22%,#91b5a8,#1b4a3a 76%);box-shadow:0 0 0 3px #8d836d,10px 13px 17px #0005;transform:rotate(-17deg);position:relative}.aff-illustration[data-tone=black] .aff-case{background:radial-gradient(circle at 30% 20%,#5d6c65,#131b19 75%)}.aff-illustration[data-tone=blue] .aff-case{background:radial-gradient(circle at 30% 20%,#9ec3cd,#193e65 75%)}.aff-illustration[data-tone=turquoise] .aff-case{background:radial-gradient(circle at 30% 20%,#c6ede0,#358798 75%)}.aff-illustration[data-tone=ivory] .aff-case{background:radial-gradient(circle at 30% 20%,#fff3d8,#a7a28a 75%)}.aff-illustration[data-tone=transparent] .aff-case{background:radial-gradient(circle at 30% 20%,#d0f3ee99,#779fa088 75%)}.aff-illustration[data-tone=silver] .aff-case{background:radial-gradient(circle at 30% 20%,#ecece4,#879a9c 75%)}.aff-illustration[data-tone=green] .aff-case{background:radial-gradient(circle at 30% 20%,#67a593,#134834 75%)}.aff-case:before,.aff-case:after{content:'';position:absolute;left:50%;bottom:50%;width:3px;background:#f9e9c8;transform-origin:bottom center}.aff-case:before{height:36px;transform:rotate(41deg)}.aff-case:after{height:48px;transform:rotate(-105deg)}.aff-case span{position:absolute;left:calc(50% - 4px);top:calc(50% - 4px);width:8px;height:8px;background:#f0d3a6;border-radius:50%}.aff-art-label{position:absolute;bottom:11px;left:12px;font-size:9px;color:#263b2e;background:#ffffffe0;padding:5px 7px;letter-spacing:.08em}.aff-card-body{padding:23px;display:flex;flex-direction:column;flex:1}.aff-card-brand{font-size:10px;font-weight:700;color:#9c7a4a;letter-spacing:.17em;text-transform:uppercase;margin:0 0 9px}.aff-card h3{font:400 25px/1.2 Georgia,serif;margin:0 0 11px}.aff-card-desc{font-size:13px;color:#606f62;line-height:1.7;margin:0 0 18px;flex:1}.aff-chips{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 17px}.aff-chips span{font-size:10px;border:1px solid #dfd4c2;color:#5e705f;padding:6px 8px}.aff-card-actions{display:grid;grid-template-columns:1fr auto;gap:9px}.aff-card-actions a{background:#203a2c;color:#fff;text-decoration:none;padding:12px 11px;font-size:12px;font-weight:650;text-align:center}.aff-card-actions a:hover{background:#385745}.aff-card-actions button{font-size:18px;min-width:46px;cursor:pointer;border:1px solid #cbbf9f;background:#f7f3e7;color:#314c38}.aff-card-actions button[aria-pressed=true]{background:#dcc696}.aff-card-foot{font-size:10px;color:#7a8078;margin-top:12px}.aff-empty{padding:50px;background:#f1eadd;text-align:center}.aff-trust{background:#e6e6df;padding:90px 0}.aff-partners{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-top:32px}.aff-partners article{background:#fafaf5;border:1px solid #d6dcd4;padding:26px}.aff-partners strong{font:400 24px Georgia,serif}.aff-partners p{font-size:13px;line-height:1.7;color:#5e7061;min-height:92px}.aff-partners a{font-size:12px;color:#28573b}.aff-small{font-size:12px;color:#687969;margin:23px 0 0}.aff-other{background:#273f32;color:#fff;text-align:center;padding:93px 0}.aff-other h2{color:#fff;margin:0 0 20px}.aff-other p:not(.overline){color:#d8e1d6;max-width:650px;margin:0 auto 30px;line-height:1.8}
@media(max-width:940px){.aff-hero-inner{grid-template-columns:1fr}.aff-copy{padding:80px 0 10px}.aff-hero-scene{height:330px}.aff-orbit{width:310px;height:310px}.aff-stage-strap{height:260px;width:95px}.aff-stage-dial{width:170px;height:170px}.aff-heading{grid-template-columns:1fr;gap:8px}.aff-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.aff-partners{grid-template-columns:1fr}.aff-partners p{min-height:0}}
@media(max-width:620px){.aff-hero-inner{gap:0}.aff-copy{padding:66px 0 0}.aff-copy h1{font-size:clamp(48px,11.6vw,68px)}.aff-tiers .wrap{grid-template-columns:1fr}.aff-tier-grid>a{min-height:135px;padding:26px}.aff-selection,.aff-trust,.aff-other{padding:65px 0}.aff-grid{grid-template-columns:1fr}.aff-illustration{height:230px}.aff-tools{display:block}.aff-query{margin-top:14px}.aff-query input{width:100%}.aff-hero-legend{font-size:8px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.aff-card{box-shadow:0 14px 40px #1b29250a;transition:transform .2s ease,box-shadow .2s ease}.aff-card:hover{transform:translateY(-5px);box-shadow:0 20px 45px #1b292520}.aff-card-actions a:focus-visible,.aff-card-actions button:focus-visible{outline:3px solid #d6b47b;outline-offset:3px}@media(prefers-reduced-motion:reduce){.aff-card{transition:none}.aff-card:hover{transform:none}}

/* Manufacturer packshots: consistent neutral art direction */
.aff-illustration:has(.aff-product-photo){background:#f5f3ed!important;padding:17px;overflow:hidden}
.aff-illustration:has(.aff-product-photo)::before{display:none}
.aff-product-photo{position:relative;z-index:1;display:block;max-width:100%;width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply;filter:drop-shadow(0 9px 9px #24332712);transition:transform .4s ease}
.aff-card:hover .aff-product-photo{transform:scale(1.045)}
.aff-illustration:has(.aff-product-photo) .aff-art-label{z-index:2;background:#173626db;color:#fff;font-size:9px;letter-spacing:.055em;max-width:calc(100% - 16px);padding:6px 9px}
@media(prefers-reduced-motion:reduce){.aff-product-photo{transition:none}.aff-card:hover .aff-product-photo{transform:none}}

/* Real product photography in the hero: preserve correct proportions on Android. */
.am-hero-watch.am-hero-real{display:flex;align-items:center;justify-content:center;overflow:visible}.am-hero-real-photo{display:block;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 22px 22px #0a1a1466)}

/* Removable filters: touch-friendly, compact and visible without opening selects. */
.am-active-filters{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:0 0 22px}.am-active-filters[hidden]{display:none}.am-filter-chip{appearance:none;border:1px solid #c7bca8;background:#e9e6dc;color:#1d3829;border-radius:100px;min-height:42px;padding:9px 15px;font:650 12px/1.4 system-ui,sans-serif;cursor:pointer;transition:background .18s ease,border-color .18s ease}.am-filter-chip:hover{background:#d9e0d5;border-color:#79977f}.am-filter-chip:focus-visible{outline:3px solid #c7a56c;outline-offset:3px}@media(prefers-reduced-motion:reduce){.am-filter-chip{transition:none}}

/* Shareable catalogue link: clear 44px touch target and safe mobile wrapping. */
.am-share-selection{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 24px}
.am-share-selection button{min-height:44px;border:1px solid #b7a88d;padding:11px 17px;background:#faf8f2;color:#244431;font:650 12px system-ui,sans-serif;letter-spacing:.025em;cursor:pointer}
.am-share-selection button:hover{background:#e9e6da}
.am-share-selection button:focus-visible{outline:3px solid #c9a668;outline-offset:3px}
.am-share-selection [role="status"]{color:#315942;font:12px/1.6 system-ui,sans-serif;overflow-wrap:anywhere;max-width:100%}
@media(max-width:620px){.am-share-selection button{width:100%;text-align:center}.am-share-selection{align-items:stretch}}

/* Device-local browsing history: restrained premium editorial cards. */
.am-recent{margin:0 0 34px;padding:22px 25px 25px;background:#f3f0e8;border:1px solid #ddd6c8}
.am-recent[hidden]{display:none}
.am-recent-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}
.am-recent-head .overline{margin:0 0 7px}
.am-recent-head h3{font:400 clamp(22px,3vw,30px)/1.15 Georgia,serif;color:#1c3428;margin:0 0 7px}
.am-recent-head p:not(.overline){font:12px/1.5 system-ui,sans-serif;color:#637365;margin:0}
.am-recent-head button{border:1px solid #aa9c83;background:transparent;color:#244735;font:650 12px system-ui,sans-serif;padding:11px 16px;min-height:44px;cursor:pointer}
.am-recent-head button:hover{background:#e7e2d6}
.am-recent-head button:focus-visible,.am-recent-card:focus-visible{outline:3px solid #c6a16a;outline-offset:3px}
.am-recent-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.am-recent-card{display:flex;align-items:center;gap:10px;min-width:0;text-decoration:none;background:#fffefa;border:1px solid #dfd9cd;padding:8px;min-height:94px;color:#1e372a;transition:border-color .18s,transform .18s}
.am-recent-card:hover{transform:translateY(-2px);border-color:#b7a073}
.am-recent-image{display:grid;place-items:center;flex:none;width:72px;height:76px;background:#f7f5ef;overflow:hidden}
.am-recent-image img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply}
.am-recent-photo-missing{font:10px/1.4 system-ui,sans-serif;text-align:center;color:#67746c}
.am-recent-name{display:flex;flex-direction:column;min-width:0;gap:4px}
.am-recent-name small{color:#947852;font:750 10px/1.35 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.08em}
.am-recent-name strong{color:#1c3828;font:650 12px/1.45 system-ui,sans-serif;overflow-wrap:anywhere}
@media(max-width:1050px){.am-recent-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
